import sympy

def is_prime(n):
    return sympy.isprime(n)

def check_good(x, y, z):
    try:
        # y^x * z^y * x^z
        # Handle negative bases and exponents
        # y^x
        if y == 0:
            if x > 0: val_yx = 0
            elif x == 0: val_yx = 1 # 0^0 = 1 usually
            else: return False # 0^neg undefined
        else:
            if x >= 0:
                val_yx = y**x
            else:
                # y^x = 1 / (y**-x)
                # For this to be an integer, y**-x must be 1 or -1
                if y == 1: val_yx = 1
                elif y == -1: val_yx = (-1)**x
                else: val_yx = 1 / (y**-x)

        # z^y
        if z == 0:
            if y > 0: val_zy = 0
            elif y == 0: val_zy = 1
            else: return False
        else:
            if y >= 0:
                val_zy = z**y
            else:
                if z == 1: val_zy = 1
                elif z == -1: val_zy = (-1)**y
                else: val_zy = 1 / (z**-y)

        # x^z
        if x == 0:
            if z > 0: val_xz = 0
            elif z == 0: val_xz = 1
            else: return False
        else:
            if z >= 0:
                val_xz = x**z
            else:
                if x == 1: val_xz = 1
                elif x == -1: val_xz = (-1)**z
                else: val_xz = 1 / (x**-z)

        res = val_yx * val_zy * val_xz
        if res == int(res) and is_prime(int(res)):
            return True
    except (ZeroDivisionError, OverflowError):
        pass
    return False

